using System;using System.IO;using System.Collections.Generic;using System.Web.Script.Serialization;using SolidWorks.Interop.sldworks;
public static class FinishMotion {
public static void Run(object app,string root){var sw=(ISldWorks)app;string path=Path.Combine(root,"solid_3mm","Motion-3mm.SLDASM");var d=(IModelDoc2)sw.GetOpenDocumentByName(path);if(d==null)throw new Exception("Motion document not open");int ae=0;sw.ActivateDoc3(d.GetTitle(),false,1,ref ae);var a=(IAssemblyDoc)d;a.EnableAssemblyRebuild=false;a.ResolveAllLightWeightComponents(false);var report=new Dictionary<string,object>();var mates=new List<object>();int gears=0,hang=0,locks=0;for(var f=(IFeature)d.FirstFeature();f!=null;f=(IFeature)f.GetNextFeature()){if(f.GetTypeName2()!="MateGroup")continue;f.Name="Motion_mates";for(var mf=(IFeature)f.GetFirstSubFeature();mf!=null;mf=(IFeature)mf.GetNextSubFeature()){var m=mf.GetSpecificFeature2() as IMate2;if(m==null)continue;var names=new List<string>();bool gondola=false;for(int i=0;i<m.GetMateEntityCount();i++){var c=m.MateEntity(i).ReferenceComponent;if(c==null)throw new Exception("World mate unexpected");names.Add(c.Name2);if(Path.GetFileName(c.GetPathName())=="gondola.SLDPRT")gondola=true;}
if(m.Type==10){var gd=(IGearMateFeatureData)mf.GetDefinition();gd.GearRatioNumerator=.06;gd.GearRatioDenominator=.025;gd.Reverse=true;if(!mf.ModifyDefinition(gd,d,null))throw new Exception("Gear modification");mf.Name="Internal_ring_60T_pinion_25T_same_direction";gears++;}
else if(m.Type==16){mf.Name="Bonded_rotor_"+names[1].Replace('-','_');locks++;}
else if(gondola){mf.Name="Hanger_"+m.Type+"_"+String.Join("_",names).Replace('-','_');hang++;}
else if(m.Type==1){var cd=(IConcentricMateFeatureData)mf.GetDefinition();if(cd.LockRotation)throw new Exception("Rotation locked");mf.Name=names.Contains("rod-1")?"Wheel_axis_free_rotation":"Pinion_axis_free_rotation";}
else mf.Name=names.Contains("rod-1")?"Wheel_axial_position":"Pinion_axial_position";
}}
// Restore the documented fabrication pose after solver checks.
var math=(IMathUtility)sw.GetMathUtility();var serializer=new JavaScriptSerializer();var v=(Dictionary<string,object>)serializer.DeserializeObject(File.ReadAllText(Path.Combine(root,"validation","native-cad-3mm.json")));foreach(Dictionary<string,object> doc in (object[])v["documents"])if((string)doc["File"]=="Assem1.SLDASM")foreach(Dictionary<string,object> co in (object[])doc["Components"]){var c=(IComponent2)a.GetComponentByName((string)co["Name"]);var arr=(object[])co["Transform"];double[] t=new double[arr.Length];for(int k=0;k<t.Length;k++)t[k]=Convert.ToDouble(arr[k]);c.Transform2=(MathTransform)math.CreateTransform(t);}
d.ForceRebuild3(false);var components=new List<object>();int fixedCount=0;foreach(object o in (object[])a.GetComponents(false)){var c=(IComponent2)o;if(c.GetSuppression()!=2||!c.GetPathName().StartsWith(Path.Combine(root,"solid_3mm"),StringComparison.OrdinalIgnoreCase))throw new Exception("Reference "+c.Name2);if(c.IsFixed())fixedCount++;components.Add(new {name=c.Name2,file=Path.GetFileName(c.GetPathName()),isFixed=c.IsFixed(),transform=(double[])c.Transform2.ArrayData});}
for(var f=(IFeature)d.FirstFeature();f!=null;f=(IFeature)f.GetNextFeature())if(f.GetTypeName2()=="MateGroup")for(var mf=(IFeature)f.GetFirstSubFeature();mf!=null;mf=(IFeature)mf.GetNextSubFeature()){var m=mf.GetSpecificFeature2() as IMate2;if(m==null)continue;bool w;int e=mf.GetErrorCode2(out w);if(e!=0||mf.IsSuppressed())throw new Exception("Mate "+mf.Name+" error="+e);mates.Add(new {name=mf.Name,type=m.Type,error=e});}
if(components.Count!=33||locks!=14||gears!=1||hang!=8||fixedCount!=13)throw new Exception("Unexpected rig counts");sw.SetUserPreferenceToggle(234,true);int se=0,ss=0;if(!d.Save3(1,ref se,ref ss)||se!=0||ss!=0)throw new Exception("Save "+se+","+ss);d.ClearSelection2(true);d.ShowNamedView2("",7);d.ViewZoomtofit2();d.SaveBMP(Path.Combine(root,"media","motion-3mm.bmp"),1600,1200);report["assembly"]="solid_3mm/Motion-3mm.SLDASM";report["components"]=components;report["mates"]=mates;report["fixedFrameComponents"]=fixedCount;report["rotorLockMates"]=locks;report["gondolaMates"]=hang;report["gearRatio"]="60:25 internal; same direction";report["staticMateErrors"]=0;report["interactiveDragVerification"]="pending; automated drag did not propagate connected components, including a separate minimal test assembly";File.WriteAllText(Path.Combine(root,"validation","motion-3mm.json"),serializer.Serialize(report));Console.WriteLine("Saved motion assembly: 33 resolved components, 27 active mates, 13 fixed frame components; static mate errors=0");}}
